-- 0017: ثلاثة بوتات تلغرام مستقلة (طلبات / دعم / تقارير) لكل منها قائمة معرّفات خاصة
CREATE TABLE IF NOT EXISTS tg_bots (bot TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, name TEXT NOT NULL DEFAULT '', token TEXT NOT NULL DEFAULT '', secret TEXT NOT NULL DEFAULT '', username TEXT NOT NULL DEFAULT '', webhook TEXT NOT NULL DEFAULT '', last_ok INTEGER NOT NULL DEFAULT 0, last_err TEXT NOT NULL DEFAULT '', last_err_at INTEGER NOT NULL DEFAULT 0, cfg TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tg_recipients (id INTEGER PRIMARY KEY AUTOINCREMENT, bot TEXT NOT NULL, chat_id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, perms TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL DEFAULT 0, last_ok INTEGER NOT NULL DEFAULT 0, last_err TEXT NOT NULL DEFAULT '', last_err_at INTEGER NOT NULL DEFAULT 0, UNIQUE(bot, chat_id));
CREATE TABLE IF NOT EXISTS tg_log (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, bot TEXT NOT NULL, chat_id TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT '', ok INTEGER NOT NULL DEFAULT 1, detail TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_tg_log ON tg_log(bot, id);
CREATE TABLE IF NOT EXISTS tg_order_msgs (order_code TEXT NOT NULL, chat_id TEXT NOT NULL, message_id INTEGER NOT NULL, PRIMARY KEY(order_code, chat_id));
CREATE TABLE IF NOT EXISTS tg_updates (bot TEXT NOT NULL, update_id INTEGER NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(bot, update_id));
